package com.civicpulse.controller;import com.civicpulse.service.AnalyticsService;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;@RestController @RequestMapping("/api/analytics") public class AnalyticsController{private final AnalyticsService service;public AnalyticsController(AnalyticsService s){service=s;}@GetMapping("/summary") @PreAuthorize("hasAnyRole('OFFICER','ADMIN')") public Map<String,Object> summary(){return service.summary();}}
